export const remap = (beat: string, s: number): number => {
  const m = TIMEMAP[beat];
  if (!m || m.length === 1) return m ? s - m[0][0] + m[0][1] : s;
  if (s <= m[0][0]) return s - m[0][0] + m[0][1];
  for (let i = 1; i < m.length; i++) {
    if (s <= m[i][0]) {
      const [o0, n0] = m[i - 1]; const [o1, n1] = m[i];
      return n0 + ((s - o0) * (n1 - n0)) / (o1 - o0);
    }
  }
  const [oL, nL] = m[m.length - 1];
  return s - oL + nL;
};
